<script setup lang="ts">
import type { EvaluationCriterion, JudgeEvaluation } from '~/types/challenge'
definePageMeta({ layout: 'challenge' })
const { state, ready, assignJudges, autoAssignJudges, saveCriteria, setBlindJudging, reopenEvaluation, teamEligible } = useChallenge()
const { t } = useI18n()
const { lt, number, date } = useChallengeFormat()
const { result } = useChallengeToast()
useHead(() => ({ title: `${t('challenge.admin.judgingTitle')} - Gaming Lab` }))
const assignmentsAllowed = computed(() => ['submission', 'judging'].includes(state.value?.competition.phase || ''))
const settingsAllowed = computed(() => !['results', 'archived'].includes(state.value?.competition.phase || ''))
const assignmentTeams = computed(() => state.value?.teams.filter(team => teamEligible(team.id) && state.value!.submissions.some(submission => submission.teamId === team.id && submission.status !== 'draft')) || [])
const criteria = ref<EvaluationCriterion[]>([])
watch(() => state.value?.criteria, value => { criteria.value = JSON.parse(JSON.stringify(value || [])) }, { immediate: true })
const totalWeight = computed(() => criteria.value.reduce((total, criterion) => total + Number(criterion.weight || 0), 0))
const criteriaValid = computed(() => totalWeight.value === 100 && criteria.value.length > 0 && criteria.value.every(item => item.name.en.trim() && item.name.ar.trim() && Number.isFinite(item.weight) && item.weight >= 0 && item.weight <= 100))
const saveWeights = () => result(saveCriteria(criteria.value), 'challenge.admin.criteriaSaved')
const assignmentOpen = ref(false)
const selectedTeamId = ref('')
const selectedJudgeIds = ref<string[]>([])
const selectedTeam = computed(() => state.value?.teams.find(team => team.id === selectedTeamId.value))
const lockedJudge = (judgeId: string) => state.value?.evaluations.some(evaluation => evaluation.teamId === selectedTeamId.value && evaluation.judgeId === judgeId && evaluation.status === 'submitted')
const conflict = (schoolId: string | null) => !!schoolId && schoolId === selectedTeam.value?.schoolId
const openAssignment = (teamId: string) => { selectedTeamId.value = teamId; selectedJudgeIds.value = state.value!.judges.filter(judge => judge.assignedTeamIds.includes(teamId)).map(judge => judge.id); assignmentOpen.value = true }
const applyAssignment = () => { if (result(assignJudges(selectedTeamId.value, selectedJudgeIds.value), 'challenge.admin.assignmentsSaved')) assignmentOpen.value = false }
const reopenOpen = ref(false)
const evaluation = ref<JudgeEvaluation | null>(null)
const reason = ref('')
const openReopen = (item: JudgeEvaluation) => { evaluation.value = item; reason.value = ''; reopenOpen.value = true }
const applyReopen = () => { if (evaluation.value && result(reopenEvaluation(evaluation.value.id, reason.value), 'challenge.admin.evaluationReopened')) reopenOpen.value = false }
const submittedEvaluations = computed(() => state.value?.evaluations.filter(item => item.status === 'submitted') || [])
</script>
<template>
  <div v-if="ready && state" class="challenge-page space-y-8"><div><h1 class="challenge-heading">{{ $t('challenge.admin.judgingTitle') }}</h1><p class="challenge-subtitle">{{ $t('challenge.admin.judgingIntro') }}</p></div>
    <section class="challenge-panel"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.judgeAssignments') }}</h2><p class="mt-2 max-w-2xl text-sm leading-relaxed">{{ $t('challenge.admin.assignmentHint') }}</p></div><button type="button" class="challenge-button" :disabled="!assignmentsAllowed || !assignmentTeams.length" @click="result(autoAssignJudges(), 'challenge.admin.assignmentsSaved')">{{ $t('challenge.admin.autoAssign') }}</button></div><p v-if="!assignmentsAllowed" class="mt-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-900">{{ $t('challenge.admin.assignmentLocked') }}</p>
      <div v-if="assignmentTeams.length" class="mt-6 divide-y divide-gray-100"><article v-for="team in assignmentTeams" :key="team.id" class="flex flex-wrap items-center justify-between gap-4 py-4"><div class="min-w-0"><h3 class="font-bold">{{ lt(team.name) }}</h3><p class="mt-1 text-xs">{{ lt(state.schools.find(school => school.id === team.schoolId)?.name) }}</p><div class="mt-2 flex flex-wrap gap-2"><ChallengeStatusPill v-for="judge in state.judges.filter(item => item.assignedTeamIds.includes(team.id))" :key="judge.id" tone="brand">{{ lt(judge.name) }}</ChallengeStatusPill><span v-if="!state.judges.some(item => item.assignedTeamIds.includes(team.id))" class="text-sm text-amber-800">{{ $t('challenge.admin.notAssigned') }}</span></div></div><button type="button" class="challenge-button-secondary" :disabled="!assignmentsAllowed" @click="openAssignment(team.id)">{{ $t('challenge.admin.assignJudges') }}</button></article></div><ChallengeEmptyState v-else :title="$t('challenge.admin.noEligibleSubmissions')" :description="$t('challenge.admin.noEligibleHint')" icon="shield-check" />
    </section>
    <section class="challenge-panel"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.criteria') }}</h2><p class="mt-2 text-sm">{{ $t('challenge.admin.criteriaHint') }}</p></div><ChallengeStatusPill :tone="totalWeight === 100 ? 'success' : 'danger'">{{ $t('challenge.admin.totalWeight') }}: {{ number(totalWeight) }}%</ChallengeStatusPill></div><form class="mt-6 space-y-5" @submit.prevent="saveWeights"><fieldset v-for="(criterion, index) in criteria" :key="criterion.id" class="grid gap-3 border-b border-gray-100 pb-5 sm:grid-cols-[1fr_1fr_115px]"><legend class="mb-3 text-sm font-semibold">{{ $t('challenge.admin.criterionNumber', { count: number(index + 1) }) }}</legend><div><label :for="`criterion-en-${criterion.id}`" class="challenge-label">{{ $t('challenge.admin.nameEn') }}</label><input :id="`criterion-en-${criterion.id}`" v-model="criterion.name.en" required maxlength="120" dir="ltr" class="challenge-field" :disabled="!settingsAllowed" /></div><div><label :for="`criterion-ar-${criterion.id}`" class="challenge-label">{{ $t('challenge.admin.nameAr') }}</label><input :id="`criterion-ar-${criterion.id}`" v-model="criterion.name.ar" required maxlength="120" dir="rtl" class="challenge-field" :disabled="!settingsAllowed" /></div><div><label :for="`criterion-weight-${criterion.id}`" class="challenge-label">{{ $t('challenge.admin.weight') }}</label><input :id="`criterion-weight-${criterion.id}`" v-model.number="criterion.weight" type="number" min="0" max="100" step="1" class="challenge-field" :disabled="!settingsAllowed" /></div></fieldset><p v-if="!settingsAllowed" class="text-sm text-amber-900">{{ $t('challenge.admin.settingsLocked') }}</p><div class="flex flex-wrap items-center justify-between gap-4"><label class="flex items-center gap-3 text-sm font-semibold"><input type="checkbox" class="h-5 w-5 accent-[#6b4aee]" :checked="state.competition.blindJudging" :disabled="!settingsAllowed" @change="result(setBlindJudging(($event.target as HTMLInputElement).checked), 'challenge.admin.blindSaved')" />{{ $t('challenge.admin.blindJudging') }}</label><button class="challenge-button" :disabled="!criteriaValid || !settingsAllowed">{{ $t('challenge.admin.saveCriteria') }}</button></div><p class="max-w-2xl text-sm leading-relaxed">{{ $t('challenge.admin.blindHint') }}</p></form></section>
    <section class="challenge-panel"><h2 class="text-xl font-bold text-heading">{{ $t('challenge.admin.lockedEvaluations') }}</h2><p class="mt-2 text-sm">{{ $t('challenge.admin.reopenHint') }}</p><div v-if="submittedEvaluations.length" class="mt-5 divide-y divide-gray-100"><article v-for="item in submittedEvaluations" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 py-4"><div><h3 class="font-semibold">{{ lt(state.teams.find(team => team.id === item.teamId)?.name) }}</h3><p class="mt-1 text-sm">{{ lt(state.judges.find(judge => judge.id === item.judgeId)?.name) }} · {{ date(item.submittedAt) }}</p></div><button type="button" class="challenge-button-secondary" :disabled="state.competition.phase !== 'judging'" @click="openReopen(item)">{{ $t('challenge.admin.reopen') }}</button></article></div><p v-else class="mt-5 text-sm">{{ $t('challenge.admin.noLockedEvaluations') }}</p><p v-if="state.competition.phase !== 'judging'" class="mt-4 text-sm text-amber-900">{{ $t('challenge.admin.reopenLocked') }}</p></section>
    <ChallengeModal v-model="assignmentOpen" :title="$t('challenge.admin.assignJudges')"><form class="space-y-5" @submit.prevent="applyAssignment"><p class="font-semibold">{{ lt(selectedTeam?.name) }}</p><p class="text-sm">{{ $t('challenge.admin.chooseJudges') }}</p><label v-for="judge in state.judges" :key="judge.id" class="flex items-start gap-3 rounded-xl border border-gray-200 p-4"><input v-model="selectedJudgeIds" :value="judge.id" type="checkbox" :disabled="conflict(judge.schoolId) || lockedJudge(judge.id)" class="mt-1 h-5 w-5 accent-[#6b4aee]" /><span class="min-w-0 flex-1"><strong class="block text-sm">{{ lt(judge.name) }}</strong><span class="mt-1 block text-xs">{{ lt(judge.expertise) }} · {{ $t('challenge.admin.assignmentCount', { count: number(judge.assignedTeamIds.length) }) }}</span><span v-if="conflict(judge.schoolId)" class="mt-2 block text-xs text-red-700">{{ $t('challenge.admin.conflict') }}</span><span v-if="lockedJudge(judge.id)" class="mt-2 block text-xs text-amber-800">{{ $t('challenge.admin.assignmentCannotRemove') }}</span></span></label><div class="flex justify-end gap-3"><button type="button" class="challenge-button-secondary" @click="assignmentOpen = false">{{ $t('challenge.shell.cancel') }}</button><button class="challenge-button" :disabled="selectedJudgeIds.length < 2 || selectedJudgeIds.length > 3">{{ $t('challenge.admin.saveAssignments') }}</button></div></form></ChallengeModal>
    <ChallengeModal v-model="reopenOpen" :title="$t('challenge.admin.reopen')"><form class="space-y-5" @submit.prevent="applyReopen"><p class="text-sm leading-relaxed">{{ $t('challenge.admin.reopenEffect') }}</p><div><label for="admin-reopen-reason" class="challenge-label">{{ $t('challenge.admin.requiredReason') }}</label><textarea id="admin-reopen-reason" v-model="reason" rows="4" class="challenge-field" required minlength="3" maxlength="1000" /></div><div class="flex justify-end gap-3"><button type="button" class="challenge-button-secondary" @click="reopenOpen = false">{{ $t('challenge.shell.cancel') }}</button><button class="challenge-button" :disabled="reason.trim().length < 3">{{ $t('challenge.admin.reopen') }}</button></div></form></ChallengeModal>
  </div><ChallengePageSkeleton v-else />
</template>
